set -eu
cd /opt/news-flow/current
[ "$(pwd -P)" = /opt/news-flow/releases/20261119-requested7-fixes-01 ]
install -d -m 700 -o news-flow -g news-flow /var/lib/news-flow/requested7-20261119/recovery
cat > scripts/requested7_recover.mjs <<'JS'
import fs from 'node:fs/promises';import {ThreeFlowState} from '../src/newsFlow/threeFlowState.mjs';import {loadNewsRegistry} from '../src/newsFlow/registry.mjs';import {NewsHttpDriver,NewsProxyPool} from '../src/newsFlow/transport.mjs';import {NewsNetworkPool} from '../src/newsFlow/networkPool.mjs';import {NewsRepairPool} from '../src/web/newsRepairPool.mjs';import {ThreeFlowProcessor} from '../src/newsFlow/threeFlowProcessor.mjs';import {articleKey,requestKey,urlAliases} from '../src/newsFlow/identity.mjs';
const dir='/var/lib/news-flow/requested7-20261119/recovery',state=await ThreeFlowState.open('/var/lib/news-flow/news-flow-runtime/write.sqlite'),registry=await loadNewsRegistry();state.loadOverlays(registry);const pool=await NewsProxyPool.load('/etc/news-flow/proxies.json',{rotation:'request'}),profiles=JSON.parse(await fs.readFile('config/web-sources/news-http-profiles.json')),network=new NewsNetworkPool({workers:1}),parsers=new NewsRepairPool(1,new URL('../src/web/newsDeepAuditWorker.mjs',import.meta.url)),driver=new NewsHttpDriver({state,pool,profiles,network,allowedDomains:registry.allowedDomains,siteCooldown:false,retryArticleTimeout:true});let offered;const processor=new ThreeFlowProcessor({state,driver,registry,parsers,maxAgeHours:Infinity,expand:false,admitRelated:false,onArticle:({doc})=>{offered={id:doc._id,index:doc._index,type:doc._type,title:doc._source.title,url:doc._source.url,publishedDate:doc._source.publishedDate};}}),urls=JSON.parse(await fs.readFile('/tmp/news-requested7-urls-20261119.json')).filter(url=>/doanhnghiepkinhdoanh\.doanhnhanvn\.vn|fili\.vn|taichinhcongnghe\.vn|banker\.vn/.test(url)),snapshots=urls.map(url=>({url,link:state.db.prepare('SELECT * FROM article_links WHERE parse_key=?').get(articleKey(url)),catalog:state.db.prepare('SELECT * FROM article_catalog WHERE url_key=?').get(requestKey(url))})),results=[];
await fs.writeFile(dir+'/before.json',JSON.stringify({at:new Date().toISOString(),snapshots},null,2));
try{for(const url of urls){offered=null;const source=registry.byUrl(url);if(!source)throw Error('SOURCE_MISSING');let task,outcome;state.tx(()=>{const key=articleKey(url),link=state.db.prepare('SELECT * FROM article_links WHERE parse_key=?').get(key);if(link?.parse_status==='done'){outcome='already_processed';return;}if(state.db.prepare("SELECT 1 FROM tasks WHERE role='article' AND state='running' AND url_key=?").get(requestKey(url))){outcome='already_running';return;}const cycle='requested7-reviewed-recovery-'+Date.now();state.cycle(cycle);state.discover(url,source.domain);state.db.prepare("UPDATE tasks SET state='skipped',reason='requested7_reviewed_refresh_superseded',lease_until=NULL WHERE role='article' AND state='pending' AND url_key=?").run(requestKey(url));const id=state.db.prepare("INSERT INTO tasks(cycle,url,url_key,site,role,priority,state,reason,created) VALUES(?,?,?,?,'article',100,'running','manual_refresh',?)").run(cycle,url,requestKey(url),source.domain,Date.now()).lastInsertRowid;state.db.prepare("UPDATE article_links SET parse_status='running',task_id=?,error=NULL,reviewed_at=? WHERE parse_key=?").run(id,Date.now(),key);task=state.db.prepare('SELECT * FROM tasks WHERE id=?').get(id);});if(!task){const row={url,outcome};results.push(row);console.log(JSON.stringify(row));continue;}try{await processor.process(task);}catch(e){await processor.hold(task,e.code||e.message);}const row={url,...state.db.prepare('SELECT state,reason FROM tasks WHERE id=?').get(task.id),offered};if(row.state==='done'&&row.reason==='verified_outbox')state.tx(()=>{for(const alias of new Set(urlAliases(url).map(requestKey)))state.db.prepare("DELETE FROM url_failures WHERE url_key=? AND role='article'").run(alias);});results.push(row);await fs.writeFile(dir+'/results.json',JSON.stringify({at:new Date().toISOString(),results},null,2));console.log(JSON.stringify(row));}if(results.some(r=>r.state==='held'))process.exitCode=1;}finally{await network.close();await parsers.close();state.close();}
JS
runuser -u news-flow -- /opt/news-flow/node/bin/node scripts/requested7_recover.mjs
